"""SQL concepts rebuilt around the meaning of one input and output row."""
SQL_TEXT = {
'basics':'''Таблица хранит строки с одинаковым набором подписанных столбцов. Строка customers описывает покупателя, строка orders — отдельный заказ. SQL задаёт вопрос к этим данным. SELECT выбирает возвращаемые значения, FROM называет источник. Начни с одного столбца, затем добавь второй и сравни форму ответа. Запрос чтения не меняет сохранённые строки. SQLite — выполняющая запрос программа, а SQL — язык: правила конкретной среды уточняют детали. До запуска назови словами, что будет означать одна строка ответа.''',
'projection':'''Из всей записи можно показать только нужные свойства. SELECT name FROM customers сохраняет по одной выходной строке для каждой подходящей исходной строки, но убирает лишние столбцы. AS даёт результату понятную подпись. Выражение может вычислить новый столбец, например увеличить сумму, не меняя исходное поле. Столбцы результата идут в записанном порядке, и автоматическая проверка учитывает этот договор. Сначала сравни исходную таблицу с ответом: какие значения исчезли из показа, какие вычислены, а какие лишь получили другое имя.''',
'filters':'''WHERE решает для каждой исходной строки, оставить её или убрать. При условии amount > 100 заказ на 100 не подходит, а на 101 подходит. SELECT определяет показанные столбцы, WHERE — отобранные строки. Это разные части вопроса. Сначала проверь условие вручную для всех маленьких исходных строк. Отсутствие результата не обязательно ошибка: возможно, никто не удовлетворяет правилу. Фильтр чтения не удаляет записи из таблицы. Для настоящего удаления существует отдельная команда, которую будем изучать позднее.''',
'logic':'''AND требует истинности обеих проверок, OR — хотя бы одной. Скобки объединяют части условия и помогают не зависеть от запоминания приоритета. Например, «покупатель 1 и сумма не меньше 100» не означает «покупатель 1 или любой дорогой заказ». Для каждой исходной строки выпиши два отдельных ответа и общий. В SQL дополнительно существует неизвестный результат из-за NULL. WHERE пропускает только истинные строки; неизвестное не приравнивается к обычному true.''',
'null':'''NULL обозначает отсутствие известного значения. Это не ноль, не пустой текст и не слово "NULL". Сравнение через = с неизвестным значением не даёт обычного ответа «да», поэтому отсутствие проверяют IS NULL, а наличие — IS NOT NULL. COALESCE позволяет явно выбрать замену, когда это соответствует смыслу задачи. Если неизвестна сумма заказа, подмена нулём меняет смысл данных. Сначала реши, нужна ли такая замена, и только затем добавляй функцию.''',
'order':'''Без ORDER BY запрос не обещает последовательность строк. Даже если сегодня записи выглядят упорядоченными по номеру, другой план исполнения может показать иной порядок. ASC сортирует по возрастанию, DESC — по убыванию. Если значения главного ключа сортировки равны, добавь устойчивый дополнительный ключ, например id. Тогда два равных по сумме заказа всё равно получат определённую последовательность. Сначала выпиши требуемый порядок словами и проверь все случаи равенства.''',
'limit':'''LIMIT ограничивает число возвращённых строк, OFFSET пропускает заданное количество перед ними. Это полезно для страниц результата, но только вместе с понятным порядком. «Первые три» без ORDER BY не обозначают устойчивые три записи. Даже с сортировкой изменения исходных данных между запросами могут сдвигать страницы. Начни с маленькой фиксированной таблицы, получи первую и вторую страницу и проверь отсутствие пропусков и повторов в этих условиях.''',
'distinct':'''DISTINCT убирает одинаковые выходные строки после выбора показанных значений. Если выбрано только имя, одинаковые имена разных людей могут слиться. Если выбраны имя и id, записи с разными id останутся различными. Поэтому DISTINCT не является универсальным исправлением «лишних строк». Сначала определи, что делает две строки одинаковыми для твоей задачи. Если повторы появились из-за неправильного JOIN, нужно проверить связь, а не скрывать следствие.''',
'range':'''BETWEEN включает обе границы. IN проверяет принадлежность одному из перечисленных значений или результату подходящего подзапроса. Для диапазона от 10 до 20 отдельно проверь 9, 10, 20 и 21. Сравнение текстовых и числовых данных зависит от типов и правил среды, поэтому сохраняй подходящий тип. NULL внутри набора особенно важен для NOT IN: неизвестное способно изменить весь вывод. Для отсутствия связей часто понятнее явно записать NOT EXISTS.''',
'like':'''LIKE сопоставляет текст с шаблоном. Знак % обозначает последовательность из нуля или более знаков, _ — один знак по правилам операции. Шаблон cat% подходит для cat и catalogue, но не требует полного равенства. Если сами % или _ должны быть обычными данными, нужен определённый способ экранирования. Правила регистра и Unicode зависят от среды SQLite и выбранных средств. Сначала проверь короткий набор строк, включая пустую, а затем формулируй общее правило поиска.''',
'case':'''CASE вычисляет значение по последовательности условий. Например, заказ может получить категорию «малый» или «крупный» по сумме. Проверки WHEN рассматриваются по правилам конструкции, а первая подошедшая ветка задаёт результат. ELSE описывает оставшийся случай; без подходящего случая и без ELSE результатом может быть NULL. Название категории не меняет исходную сумму. Сначала разметь каждую строку вручную и особенно проверь значение на границе двух категорий.''',
'aggregate':'''Агрегат собирает несколько строк в один показатель. COUNT(*) считает строки, COUNT(amount) — строки с известным amount. SUM складывает известные значения, AVG получает среднее по подходящим значениям, MIN и MAX выбирают крайние. Эти функции не обязаны одинаково отвечать на пустой набор: COUNT даёт 0, а SUM без строк обычно даёт NULL. До запроса запиши, что именно считаешь: заказы, покупателей или известные суммы. Одинаковое внешнее число может скрывать разные вопросы.''',
'group':'''GROUP BY делит строки на группы с одинаковыми значениями выбранного ключа. Если ключ customer_id, один итог относится к одному покупателю, а не к одному заказу. В группе считаются SUM, COUNT и другие показатели. Показывай неагрегированные значения так, чтобы их смысл был определён для всей группы. Особенности SQLite не стоит использовать ради случайного имени из одной из строк. Сначала нарисуй маленькие группы, затем вручную сложи каждую отдельно.''',
'having':'''WHERE отбирает отдельные исходные строки до объединения в группы. HAVING отбирает уже полученные группы по их показателям. «Покупатели, чья общая сумма больше 100» требует сначала посчитать общий итог. Если сначала отбросить все заказы не дороже 100, вопрос станет другим и небольшие покупки исчезнут из суммы. Пройди этапы отдельно: исходные записи, отбор, группы, показатели, отбор групп. Укажи, где именно проверяется каждое условие.''',
'inner':'''INNER JOIN создаёт строку для каждой пары записей, удовлетворяющей условию ON. Например, orders.customer_id связывается с customers.id. Это не склейка по номеру позиции в двух таблицах. У одного покупателя может быть несколько заказов, поэтому его данные повторятся в нескольких выходных строках. Покупатель без заказа не попадёт в такое соединение. Для проверки сначала выпиши пары идентификаторов, затем добавляй нужные столбцы показа.''',
'left':'''LEFT JOIN сохраняет каждую строку слева. Если подходящей пары справа нет, правые поля результата заполняются NULL. Так можно увидеть покупателя даже без заказов. Условие правой таблицы в WHERE способно убрать такую строку после соединения и изменить смысл сохранения. Если нужно ограничить подходящие пары, подумай об условии ON. Проверяй три случая: одна пара, несколько пар, ни одной. COUNT(*) и COUNT(orders.id) при отсутствии заказа дадут разный смысл.''',
'multiplicity':'''Соединение может размножать строки. Если у покупателя два заказа и три записи другого связанного списка, их совместное соединение может дать шесть сочетаний. Сумма заказа повторится и станет завышенной. До суммирования определи, что означает одна строка каждого промежуточного набора. Иногда нужно сначала собрать итог отдельно по покупателю, а потом соединять итоги. DISTINCT не объясняет причину и способен скрыть правильные одинаковые значения. Начни с подсчёта пар на двух маленьких списках.''',
'subquery':'''Подзапрос — запрос внутри другого запроса. Он может дать одно значение, список значений или табличный результат, и место использования должно соответствовать его форме. Например, общий средний заказ можно вычислить отдельно и сравнивать с ним каждую сумму. Коррелированный подзапрос обращается к текущей строке внешнего запроса и задаёт связанный с ней вопрос. Сначала выполни внутренний запрос самостоятельно. Затем объясни, какие данные он получает и что возвращает внешнему уровню.''',
'exists':'''EXISTS отвечает, появилась ли хотя бы одна строка во внутреннем запросе. Для вопроса «есть ли у покупателя заказ» не нужно суммировать заказы или показывать их все. Внешняя строка сохраняется по факту наличия хотя бы одного совпадения. Повторы внутренних совпадений не размножают внешнего покупателя. Сначала возьми одного покупателя с несколькими заказами и одного без заказов. Проверь, что первый появляется один раз, а второй не появляется.''',
'anti':'''NOT EXISTS выражает отсутствие подходящих строк. Например, для каждого покупателя спрашиваем, нет ли заказа с его номером. Покупатель без заказов подходит, с одним или несколькими — нет. Это не то же самое, что искать строку заказа с нулевой суммой. При варианте с LEFT JOIN проверяй отсутствие по столбцу, который у настоящей связанной записи не может быть NULL. Для NOT IN отдельно учитывай неизвестные значения: их влияние часто неожиданно новичку.''',
'cte':'''WITH даёт имя результату запроса внутри одной SQL-команды. Так длинный расчёт можно читать как несколько этапов: подготовили продажи, собрали итоги, выбрали подходящие группы. Обычный CTE не создаёт постоянную таблицу для следующего независимого запуска. Его имя действует в пределах текущей команды. Сначала выполни запрос этапа отдельно и проверь смысл строки. Затем соедини этапы, сохраняя понятные имена. Материализация и скорость зависят от плана, а не только от наличия WITH.''',
'sets':'''UNION объединяет результаты и убирает одинаковые строки, UNION ALL сохраняет все повторы. INTERSECT оставляет общие строки, EXCEPT — строки первого результата, которых нет во втором. Позиции столбцов должны иметь совместимый смысл: номер покупателя нельзя случайно объединять с суммой заказа. Окончательный порядок задаётся отдельно. Сначала выпиши два небольших набора с одним повтором и покажи результат каждого действия вручную. Затем проверь, нужны ли повторы по смыслу задачи.''',
'window':'''Оконная функция вычисляет показатель для группы связанных строк, не сворачивая их в одну строку как GROUP BY. Например, рядом с каждым заказом можно показать общую сумму заказов покупателя. PARTITION BY задаёт отдельные группы вычисления. ORDER BY внутри окна задаёт порядок расчёта, а не гарантирует внешний порядок вывода. Для накопления также важна рамка окна — набор строк, входящих в текущий расчёт. Начни с трёх заказов одного покупателя и подпиши показатель возле каждого.''',
'ranking':'''ROW_NUMBER присваивает разные последовательные номера строкам в выбранном порядке. RANK даёт одинаковый ранг равным ключевым значениям и оставляет пропуск после равенства; DENSE_RANK такого пропуска не оставляет. Например, суммы 100, 100, 50 показывают разницу правил. Реши, что означает «первое место» и как обращаться с ничьей. Дополнительный уникальный ключ делает нумерацию воспроизводимой, но его включение в само определение ничьей может изменить смысл ранга.''',
'running':'''Накопительный итог после первой строки равен её сумме, после второй — сумме первых двух и так далее. Порядок должен быть определён: например, id заказа. Для построчного накопления явно укажи ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW. Рамка RANGE имеет другое поведение при равных ключах порядка. Сначала посчитай каждый промежуточный итог вручную и сравни все строки, а не только последнюю сумму. Финальную последовательность показа задай внешним ORDER BY.''',
'lag':'''LAG получает значение предыдущей строки в выбранном оконном порядке, LEAD — следующей. Первая строка не имеет предыдущей, поэтому без иной настройки получается NULL. Разность текущей и предыдущей суммы показывает изменение, а не накопление. PARTITION BY не позволяет случайно сравнить последний заказ одного покупателя с первым другого. Сначала подпиши для каждой строки номер её соседа. Потом вычисляй разность и отдельно объясни отсутствие соседа на границе.''',
'recursive':'''Рекурсивный CTE начинает с начальных строк и повторяет шаг, который создаёт новые строки из уже полученных. Для чисел 1…5 стартом служит 1, шагом — прибавление единицы при допустимой границе. Нужно заранее понять, почему новые строки перестанут появляться. Условие завершения особенно важно при обходе циклических связей. UNION и UNION ALL по-разному обращаются с повторами. Сначала выпиши первые три поколения строк вручную и найди, где остановится пример.''',
'schema':'''Схема описывает, какие сущности хранятся и как связаны. Книга как произведение и её физический экземпляр — разные вещи: два экземпляра могут иметь общий book_id и разные собственные id. PRIMARY KEY обозначает уникальную запись. FOREIGN KEY связывает запись с существующей другой записью, когда соответствующая проверка включена. Сначала нарисуй две маленькие таблицы и стрелки номеров. Затем создай их и проверь допустимую связь и ссылку на несуществующую книгу.''',
'constraints':'''Ограничения проверяет сама база при изменении данных. NOT NULL запрещает отсутствие, UNIQUE ограничивает повторы по выбранному правилу, CHECK проверяет выражение, FOREIGN KEY — допустимость ссылки. Каждое ограничение защищает конкретный смысл, например неотрицательную цену. После неудачной вставки прочитай таблицу и убедись, что запрещённая запись не появилась. Эти средства не заменяют понятные сообщения интерфейса, но защищают данные и от другого клиента. В SQLite включение внешних ключей требуется для каждого соединения.''',
'normalization':'''Если имя покупателя записывать заново в каждом его заказе, переименование потребует менять много строк. Одну можно пропустить и получить противоречие. Выделение customers хранит имя один раз, а orders ссылается на номер. Это устраняет конкретную аномалию обновления. Нормализация — способ организовать зависимости данных, а не требование сделать как можно больше таблиц. Сначала перечисли, какие свойства зависят от какого номера, затем разделяй повторяемые сведения. Проверь переименование и неизменность числа заказов.''',
'insert':'''INSERT добавляет новые записи, поэтому до запуска проверь таблицу назначения и порядок полей. Явное перечисление имён столбцов делает договор понятнее. В программе значения передают отдельными параметрами API; вопросительный знак — место параметра, а не готовое значение для ручного запроса. Имя с апострофом должно оставаться данными и не менять структуру команды. После добавления прочитай запись по её номеру. Отдельно проверь нарушение уникальности и отсутствие обязательного поля.''',
'update':'''UPDATE меняет найденные записи, DELETE удаляет их. Без WHERE действие может затронуть всю таблицу. Перед изменением выполни SELECT с тем же условием и проверь, какие строки выбраны. Для нескольких связанных изменений используй транзакцию. После операции проверь число и содержимое затронутых записей, а не только отсутствие ошибки. Удаление родительской записи зависит от внешних ключей и выбранных действий связи. Учись на отдельной тестовой базе с резервной копией.''',
'transactions':'''Транзакция объединяет изменения в одну работу. COMMIT подтверждает её, ROLLBACK отменяет незавершённые изменения. Для перевода между счетами недостаточно уменьшить первый баланс: увеличение второго должно пройти вместе с ним или оба изменения должны отмениться. Сначала запиши состояние до, после успеха и после отказа посередине. Ошибка одной команды не всегда означает автоматический откат всего нужного тебе сценария. Приложение должно явно проверить исход и завершить транзакцию по договору.''',
'isolation':'''Когда два клиента работают с базой, каждый может видеть состояние в определённый момент и пытаться изменить его. Если оба прочитали один старый остаток и независимо записали новый, одно изменение можно потерять. Транзакции, блокировки и условное обновление помогают организовать такую работу, но правила зависят от СУБД. SQLite имеет свои ограничения одновременной записи. Сначала разыграй порядок двух клиентов на бумаге: чтение A, чтение B, запись A, запись B. Затем выбери способ не потерять действие.''',
'indexes':'''Индекс — дополнительная структура для поиска, обычно связанная со значениями выбранных столбцов и адресами строк. Он может ускорить подходящий фильтр или сортировку, но занимает место и требует обновления при записи. Наличие индекса не означает ускорение любого запроса. Порядок полей составного индекса влияет на полезность. Начни с одного частого условия поиска и сравни план до и после индекса. Измеряй на достаточных данных, сохраняя одинаковый смысл результата.''',
'plan':'''EXPLAIN QUERY PLAN в SQLite показывает выбранный способ получения результата. SCAN и SEARCH помогают понять, выполняется ли проход и используется ли подходящий доступ. План описывает исполнение, а не меняет смысл SQL. Сначала проверь правильность результата, потом исследуй стоимость. Один быстрый запуск на трёх строках не доказывает полезность индекса на больших данных. Сравни несколько размеров, одинаковые входы и повторяемые условия. Читай конкретные указанные таблицы и индексы, а не только ищи слово INDEX.''',
'security':'''SQL-инъекция возникает, когда данные пользователя становятся частью текста команды. Имя с кавычкой должно передаваться параметром, а не склейкой SQL-строки. Параметры подходят для значений, но не заменяют произвольные имена столбцов: такие варианты выбирают из разрешённого списка. Дополнительно ограничивай доступ к файлу базы и права приложения. Учебный локальный режим не является полной песочницей для чужого кода. Начни с имени с апострофом и проверь сохранение точного текста без изменения структуры запроса.''',
'migration':'''Миграция переводит схему и данные к новой версии. Добавление обязательного поля требует решить, какие значения получат старые строки. Перед изменением сделай согласованную резервную копию и проверь восстановление в отдельной базе. Копирование одного файла работающей базы без учёта режима журналирования может не дать нужного снимка. Записывай версию и последовательность шагов. Сначала отработай переход на маленькой копии, проверь число строк и ключевые запросы, а затем применяй к рабочим данным.''',
'project':'''Для аналитики магазина сначала определи сущности: покупатели и отдельные заказы. Наполни маленький набор так, чтобы вручную проверить отсутствие заказов, несколько заказов и одинаковые суммы. Построй отчёт по покупателю, не размножая суммы соединением. Затем добавь категории и период, явно определив границы дат. Для каждого отчёта запиши смысл строки и столбцов. После правильности изучи план и нужные индексы. Сохрани схему, данные примера и ожидаемые результаты как воспроизводимую работу.''',
'graduation':'''База библиотеки должна различать книги, экземпляры, читателей и выдачи. Один экземпляр нельзя одновременно выдать двум людям, если это запрещено правилами. Сначала нарисуй связи и объясни, где хранится каждый факт. Затем создай ограничения и транзакцию выдачи. Проверь успех, отсутствие экземпляра, повторную выдачу и отказ посередине. Подготовь отчёты просрочек и истории без случайного удвоения строк. Итогом служит не прочитанная страница, а схема, запросы, тестовые данные и объяснение причин правильности.''',
'islands':'''Нужно объединить подряд идущие дни активности в отдельные цепочки. Сначала убираем повтор одного дня одного пользователя: несколько событий не должны удлинять цепочку дней. Затем нумеруем даты внутри пользователя. Разность номера дня и его последовательного номера остаётся постоянной внутри непрерывного участка. По этому ключу собираем начало, конец и длину. Проверь два соседних дня, пропуск и повтор дня. Каждый промежуточный этап показывает свою единицу данных: событие, уникальный день, строка с ключом, готовый участок.''',
'sessions':'''Сессия объединяет события пользователя, между которыми нет слишком большого перерыва. Сначала через LAG получаем предыдущее время внутри пользователя. Первая запись и запись после перерыва больше порога начинают новую сессию. Накопительная сумма таких признаков даёт номер сессии. Граница ровно в порог и больше порога должна быть оговорена. При равном времени добавь id для устойчивого порядка. Не группируй разных пользователей вместе и не считай номер сессии только по календарному дню.''',
'cohorts':'''Когорта объединяет пользователей по моменту начала, например месяцу первой активности. Удержание спрашивает, сколько разных участников этой группы вернулось через заданное число месяцев. Несколько событий одного человека за месяц не являются несколькими вернувшимися людьми. Сначала получи один факт активности на пользователя и месяц. Потом найди месяц начала и смещение месяца. Лишь затем считай участников. Проверь пользователя с повторными событиями и пользователя без возврата. Договорись, что означает знаменатель доли.''',
'hierarchy':'''Иерархия хранит связь записи с родителем. Для обхода начинаем с выбранных корней и на каждом шаге добавляем детей. Глубина увеличивается на один, путь помогает объяснить, как запись достигнута. В ошибочных данных могут быть циклы; ограничение глубины или проверка пути предотвращает бесконечное повторение по выбранному договору. Записи без достижимого корня требуют отдельной проверки и не появляются волшебно в результате корневого обхода. Сначала нарисуй дерево из пяти узлов и сравни каждую строку пути.''',
'reachability':'''Достижимость отвечает, можно ли из начальной вершины попасть в другую по связям. Если граф содержит цикл, одна вершина может встречаться по многим путям. Для набора достигнутых номеров UNION убирает уже появившиеся строки и помогает завершить такой расчёт. Если добавить в строку путь или глубину, строки снова могут стать различными и прежнее рассуждение о завершении перестанет работать. Сначала задай смысл строки рекурсивного отношения, затем выбери правило повторов. Проверь цикл и отдельную недостижимую вершину.''',
'division':'''Нужно найти участников, выполнивших все обязательные требования. «Есть хотя бы одно выполнение» недостаточно. Удобно спросить: нет ли обязательного требования, для которого у участника отсутствует выполнение. Повтор одного выполнения не заменяет другое требование. Поэтому простой подсчёт всех строк опасен. Сначала выпиши множество требований и завершения каждого участника. Отдельно договорись о пустом наборе требований: по логическому смыслу отсутствуют невыполненные требования у всех рассматриваемых участников.''',
'pareto':'''Для анализа вклада сначала получаем одну сумму на категорию. Затем считаем общий итог и накопленный вклад в выбранном порядке категорий. Доля требует правильного числового деления и обработки нулевого общего итога. При равных суммах нужен дополнительный устойчивый порядок, если отчёт должен повторяться. Уточни, включается ли категория, пересекающая заданный порог. Сначала посчитай три категории вручную, затем сравни каждую накопительную строку и только после этого выбирай нужную часть отчёта.''',
'ledger':'''Проводки описывают изменения счёта по времени или номеру. Баланс после строки равен начальному балансу и сумме всех изменений до неё включительно. Для аудита важно найти первое нарушение, а не только отрицательный итог в конце. Сначала задай полный порядок внутри каждого счёта, затем получи накопление и проверку. Повторный номер или неоднозначное время требует дополнительного ключа. Сохраняй отдельные проводки в результате, чтобы было видно происхождение нарушения и можно было проверить промежуточные шаги.''',
}
